WFJ.Data.add("spell", {
  [408024] = { "使用すると最大体力の$N1%を得て、$D1の間、与えるPhysical以外のすべての回復量を$N2%増加させます。効果が切れると、得た体力は失われます。Moonkin Form以外のすべてのフォームで使用できます。\n\nさらに、Bear FormまたはDire Bear Formでは回避するたびに怒りを$N4、Cat Formではエネルギーを$N5、その他のフォームでは最大マナの$N6%を回復します。", "体力が最大値の$N1%増加しています。", 0xf0735027, 0x414996c4, "uu" },
  [408120] = { "$D1かけて対象とそのパーティを$N1回復します。パーティメンバーは対象から$N3ヤード以内にいる必要があります。回復は最初は速く、Wild Growthの効果時間が終わりに近づくにつれて遅くなります。", "$N2秒ごとに$N1のダメージを回復します。", 0x1cb536f6, 0xcf751a77, "uu" },
  [408124] = { "$D1かけて対象を$N1回復します。Lifebloomの効果時間が終了するか解除されると、対象は即座に$N3回復し、ドルイドは呪文のコストの半分を取り戻します。この効果は同じ対象に最大$N4回まで重なります。", "毎秒$N1回復し、効果が終了するか解除されたときに$N2回復します。", 0x8ddbb673, 0x57b19551, "uu" },
  [408245] = { "$N1秒かけて対象を回復します。Lifebloomの効果時間が終了するか解除されると、対象は即座に回復します。この効果は同じ対象に最大$N2回まで重なります。", nil, 0x2a59bfb7, nil, "um" },
  [408246] = { "Lifebloomが切れたときにマナを得ています。", nil, 0xa7aa89d1, nil, "um" },
  [408247] = { "友好的な対象を$N1回復します。対象にRejuvenation、Regrowth、Lifebloom、Wild Growthの効果がかかっている場合、さらに$N2%回復します。この呪文はHealing TouchまたはRegrowthに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0x2a601efa, nil, "um" },
  [408248] = { "Wrathの呪文により、次に唱える$N1回分のStarfireの詠唱時間が$N2秒短縮されます。最大$N3チャージまで蓄積できます。$D2持続します。", nil, 0x90e893e0, nil, "um" },
  [408255] = { nil, "次の$N1回のStarfireの詠唱時間が$D1短縮されます。", nil, 0x727e4f27, "mu" },
  [408258] = { "持続型でないダメージ呪文がクリティカルになると、$D1の間、詠唱中もマナ回復の$N1%が継続します。", nil, 0x0e52fe0b, nil, "um" },
  [408261] = { "詠唱中もマナ回復の$N1%が継続します。", "呪文の詠唱中も通常のマナ回復の$N1%が継続します。", 0x86815c0c, 0x7a27f000, "uu" },
  [408307] = { "$D1の間、治癒力がNature呪文ダメージの$N1%だけ増加します。", "回復の威力が$N1増加します。", 0x582306b5, 0xfda8744a, "uu" },
  [408309] = { "呪文ダメージが、治癒力と呪文ダメージの差の$N1%だけ増加します。$D1持続します。", "呪文ダメージが$N1増加します。", 0xd596949e, 0x62dc13bd, "uu" },
  [408339] = { "Fire Nova Totemの呪文がFire Novaに置き換わります。Fire Novaは現在のFireトーテムからその位置にダメージを放出させます。", nil, 0x2cf7852b, nil, "um" },
  [408341] = { "有効なFireトーテムから$N2ヤード以内の敵に、即座に$N1の火炎ダメージを与えます。", nil, 0x7d542fd2, nil, "um" },
  [408342] = { "有効なFireトーテムから$N2ヤード以内の敵に、即座に$N1の火炎ダメージを与えます。", nil, 0xe2e3227a, nil, "um" },
  [408343] = { "有効なFireトーテムから$N2ヤード以内の敵に、即座に$N1の火炎ダメージを与えます。", nil, 0x0fd89bbd, nil, "um" },
