  [408345] = { "有効なFireトーテムから$N2ヤード以内の敵に、即座に$N1の火炎ダメージを与えます。", nil, 0x2fb7f4c2, nil, "um" },
  [408438] = { "Lightning BoltとChain Lightningに、$N1%の確率で同じ対象にもう一度、似た呪文を追加コストなしで唱える効果を与えます。その呪文のダメージは半分で、脅威を発生させません。", nil, 0x43e46bfc, nil, "um" },
