  [408479] = { "敵に稲妻を投げつけ、$N1のNatureダメージを与えた後、周囲の敵に飛び移ります。飛び移るたびにダメージは$N2%減少します。対象は合計$N3体です。", nil, 0xbf3e3b89, nil, "um" },
  [408481] = { "敵に稲妻を投げつけ、$N1のNatureダメージを与えた後、周囲の敵に飛び移ります。飛び移るたびにダメージは$N2%減少します。対象は合計$N3体です。", nil, 0xbf3e3b89, nil, "um" },
  [408482] = { "敵に稲妻を投げつけ、$N1のNatureダメージを与えた後、周囲の敵に飛び移ります。飛び移るたびにダメージは$N2%減少します。対象は合計$N3体です。", nil, 0xbf3e3b89, nil, "um" },
  [408484] = { "敵に稲妻を投げつけ、$N1のNatureダメージを与えた後、周囲の敵に飛び移ります。飛び移るたびにダメージは$N2%減少します。対象は合計$N3体です。", nil, 0xbf3e3b89, nil, "um" },
  [408490] = { "対象に溶岩を投げつけ、$N1のFireダメージを与えます。対象にFlame Shockがかかっている場合、Lava Burstのダメージが$N2%増加します。", nil, 0xc9c1c783, nil, "um" },
  [408491] = { "対象に溶岩を投げつけ、$N1のFireダメージを与えます。対象にFlame Shockがかかっている場合、Lava Burstのダメージが$N2%増加します。", nil, 0x2838b0c8, nil, "um" },
  [408496] = { "二刀流の間、呪文と近接攻撃の両方の命中率が$N1%上昇し、Stormstrikeのアビリティが二刀流時に両方の武器で命中するようになり、オフハンド武器の与えるダメージが$N2%増加します。", nil, 0x33e038b0, nil, "um" },
  [408498] = { "近接攻撃でダメージを与えると、一定の確率で次のLightning Boltの詠唱時間とマナコストを$N1%軽減します。最大$N2回まで重なります。効果時間は$D1です。", nil, 0x9a6cb9c7, nil, "um" },
  [408505] = { "次のLightning Boltの呪文の詠唱時間とマナコストを減少させます。", "次のLightning Boltの呪文の詠唱時間とマナコストが$N1%減少します。", 0xe17bbdf5, 0xf55df514, "uu" },
  [408507] = { "オフハンド武器に溶岩をまとわせ、即座にオフハンドWeaponダメージの$N1%を与えます。オフハンド武器にFlametongueのエンチャントが施されている場合、ダメージが$N2%増加します。", nil, 0xfd5176b5, nil, "um" },
  [408510] = { "術者は$N1個の水の球に囲まれます。呪文、近接攻撃、遠隔攻撃が術者に命中するか、術者の回復呪文がクリティカルになると、最大マナの$N2%が術者に回復し、水の球を一つ消費します。球が発動するのは数秒に一度だけです。効果時間は$D1です。\n\nシャーマンにかけられるElemental Shieldは一度に一つだけです。", "自分に使われた攻撃と呪文、および自分のクリティカル治療で、最大マナの$N1%を回復します。残り$N2回。", 0x4b7bfd54, 0xda097360, "uu" },
  [408511] = { "Water Shieldが有効な間に攻撃を受けるとマナを得ています。", nil, 0x1d96f43d, nil, "um" },
  [408514] = { "対象を大地のシールドで守り、ダメージを受けたときに失われる詠唱時間または精神集中時間を$N1%軽減し、攻撃を受けるとシールドを張った対象を$N2回復させます。この効果は数秒に一度しか発生しません。チャージ数は$N3です。効果時間は$D1です。Earth Shieldは一度に一体の対象にしかかけられません。", "ダメージを受けたときに失う詠唱時間または集中時間が$N1%減少し、攻撃を受けると守られている目標を$N2回復します。", 0xbdee3645, 0x38d681af, "uu" },
  [408519] = { "Earth Shieldによって回復しました。", nil, 0x1dc3ad48, nil, "um" },
  [408521] = { "友好的な対象を$N1回復し、さらに$D1かけて$N2回復します。また、その対象に直接唱えるChain Healの効果を$N4%高めます。", "$N2秒ごとに$N1回復します。\nこの目標に直接詠唱された術者のChain Healの効果が$N3%上昇します。", 0x68320edf, 0x0b6d739c, "uu" },
  [408524] = { "Blockするたびに、最大マナの$N1%に等しいマナを回復し、盾のアーマー値の$N2%に等しいアーマーを得ます。最大$N3回までスタックします。また、Blockの確率が常に$N4%上昇し、Block値が$N5%上昇します。\n\nさらに、Shockのアビリティを使用するたびに、防御スキルが$N7を超えるポイントごとにSpell Damageを$N6得ます。$D1持続します。", nil, 0x6633c263, nil, "um" },
  [408525] = { "$D1の間、アーマーが盾のアーマー値の$N1%だけ増加します。最大$N3回までスタックします。", "アーマーが$N1増加します。", 0x8525df7d, 0x97da7cad, "uu" },
  [408531] = { "メインハンド武器にRockbiter Weaponが有効で盾を装備している間、発生する脅威が$N1%増加し、体力が$N2%増加し、受けるダメージが$N3%減少し、近接攻撃でクリティカルヒットを受ける確率が$N4%減少します。またEarth Shockが対象をTauntして自分を攻撃させるようになり、他のShock呪文とは別のクールダウンになりますが、射程は近接距離に短縮されます。ただし、Lightning Bolt、Chain Lightning、Chain Heal、Healing Wave、Lava Burstの呪文の射程が$N5ヤード短くなります。", nil, 0x27fc7143, nil, "um" },
  [408680] = { "メインハンド武器にRockbiter Weaponが有効な間、発生する脅威が$N1%増加し、体力が$N2%増加し、受けるダメージが$N3%減少し、近接攻撃でクリティカルヒットを受ける確率が$N4%減少します。またEarth Shockが対象をTauntして自分を攻撃させるようになり、他のShock呪文とは別のクールダウンになります。", "発生させる脅威が$N1%増加します。体力が$N2%増加します。Earth ShockでTauntsが発動し、目標にあなたを攻撃させます。受けるダメージが$N3%減少します。近接攻撃でクリティカルを受ける確率が$N4%減少します。", 0xefe15a43, 0xf9b0daa9, "uu" },
  [408681] = { "衝撃の力で対象を即座に打ち、$N1のNatureダメージを与えます。また詠唱を妨害し、$D1の間その系統の呪文を詠唱できなくします。大量の脅威を発生させ、対象をTauntします。", "挑発されています。", 0xcc9d1126, 0x36f56123, "uu" },
  [408683] = { "衝撃の力で対象を即座に打ち、$N1のNatureダメージを与えます。また詠唱を妨害し、$D1の間その系統の呪文を詠唱できなくします。大量の脅威を発生させ、対象をTauntします。", "挑発されています。", 0xcc9d1126, 0x36f56123, "uu" },
